    public static void testASixteenBitSampleReducesByTheStatedRule() {
        // (v * 255 + 32767) / 65535: 0 -> 0, 128 -> 0, 129 -> 1, 32767 -> 127, 32768 -> 128, 65535 -> 255.
        emon.Port.Cells ar = emon.Port.newCells();
        emon.Port.Cells dc = emon.Port.newCells();
        emon.Port.Cells a = emon.Port.newCells();
        emon.Port.Cells b = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells im = emon.Port.newCells();
        emon.Port.Cells smp = emon.Port.newCells();
        emon.Port.Cells dmi = emon.Port.newCells();
        emon.Port.Cells dms = emon.Port.newCells();
        int sh = 0;
        emon.Port.Src src = emon.Port.srcOfBlob(emon.Testport.testFile("assets/flate-rgb16.pdf"));
        emon.Testport.assertEq(Pdfdoc.pdOpen(src, ar, dc, a, b, st), 0, "the file opens");
        sh = Pdfdoc.pdGet(src, ar, dc, a, b, st, 5);
        emon.Testport.assertEq(Pdfimage.piInfo(src, ar, dc, a, b, st, out, im, sh, 5), 0, "the image is read");
        emon.Testport.assertEq(Pdfimage.piGet(im, Pdfimage.piFW()), 17, "its width");
        emon.Testport.assertEq(Pdfimage.piGet(im, Pdfimage.piFH()), 11, "its height");
        emon.Testport.assertEq(Pdfimage.piSamples(src, ar, dc, a, b, st, im, sh, smp), 0, "the samples decode");
        emon.Testport.assertEq(emon.Port.cellsLen(smp), (17 * 11) * 6, "six bytes a pixel");
        int i = 0;
        while (i < 6) {
            emon.Port.cellsSet(smp, i, 0);
            i += 1;
        }
        emon.Port.cellsSet(smp, 0, 0);
        emon.Port.cellsSet(smp, 1, 128);
        emon.Port.cellsSet(smp, 2, 0);
        emon.Port.cellsSet(smp, 3, 129);
        emon.Port.cellsSet(smp, 4, 127);
        emon.Port.cellsSet(smp, 5, 255);
        Pdfimage.piView(im, 0);
        emon.Port.Bitmap pic = emon.Port.bitmapNew(17, 11, 3);
        emon.Port.Bitmap al = emon.Port.bitmapNew(17, 11, 1);
        emon.Testport.assertEq(Pdfimage.piPixels(im, smp, pic, dmi, dms, pic, 0, 0, pic, al), 0, "the pixels are made");
        emon.Testport.assertEq(emon.Port.bitmapU8(pic, 0, 0, 0), 0, "0 is 0");
        emon.Testport.assertEq(emon.Port.bitmapU8(pic, 0, 0, 1), 1, "129 is 1");
        emon.Testport.assertEq(emon.Port.bitmapU8(pic, 0, 0, 2), 127, "32767 is 127");
    }
