    public static int itHexCells(byte[] b, emon.Port.Cells c) {
        // The bytes of a `hex-blob` as one cell each.
        int i = 0;
        emon.Port.cellsDrop(c, 0);
        while (i < emon.Port.blobLen(b)) {
            emon.Port.cellsPush(c, emon.Port.blobU8(b, i));
            i += 1;
        }
        return 0;
    }
